from pathlib import Path

from firmloop.hardware.codegen import generate_channels_cpp, generate_drivers_cpp
from firmloop.hardware.registry import Registry

EXPECTED_CHANNELS_NATIVE = """\
// Generated by firmloop codegen. Do not edit.
#include "FirmLoopInternal.h"

namespace fl {

const ChannelDef CHANNELS[] = {
    {"button", Type::Bool, Kind::Sensor, 0.0f},
    {"buzzer", Type::Bool, Kind::Actuator, 0.0f},
    {"display", Type::Text, Kind::Display, 0.0f},
    {"fan", Type::Bool, Kind::Actuator, 0.0f},
    {"humidity", Type::Float, Kind::Sensor, 50.0f},
    {"led", Type::Bool, Kind::Actuator, 0.0f},
    {"light", Type::Int, Kind::Sensor, 2000.0f},
    {"motion", Type::Bool, Kind::Sensor, 0.0f},
    {"temp", Type::Float, Kind::Sensor, 25.0f},
};
const uint8_t CHANNEL_COUNT = 9;
const char* const FW_ID = "native";

}  // namespace fl
"""

EXPECTED_DRIVERS = """\
// Generated by firmloop codegen. Do not edit.
#include "FirmLoopInternal.h"
#include "src/button/driver.h"
#include "src/buzzer/driver.h"
#include "src/dht22/driver.h"
#include "src/ldr/driver.h"
#include "src/led/driver.h"
#include "src/pir/driver.h"
#include "src/relay_fan/driver.h"
#include "src/ssd1306/driver.h"

static ButtonDriver driver_button(19);
static BuzzerDriver driver_buzzer(25);
static Dht22Driver driver_dht22(4);
static LdrDriver driver_ldr(34);
static LedDriver driver_led(18);
static PirDriver driver_pir(27);
static RelayDriver driver_relay_fan(26);
static Ssd1306Driver driver_ssd1306(21, 22);

namespace fl {

Driver* const DRIVERS[] = {
    &driver_button,
    &driver_buzzer,
    &driver_dht22,
    &driver_ldr,
    &driver_led,
    &driver_pir,
    &driver_relay_fan,
    &driver_ssd1306,
};
const uint8_t DRIVER_COUNT = 8;

}  // namespace fl
"""


def test_channels_snapshot_native(real_hardware: Path) -> None:
    assert generate_channels_cpp(Registry.load(real_hardware), "native") == EXPECTED_CHANNELS_NATIVE


def test_channels_sorted_by_id(real_hardware: Path) -> None:
    text = generate_channels_cpp(Registry.load(real_hardware), "native")
    ids = [line.split('"')[1] for line in text.splitlines() if line.startswith("    {")]
    assert ids == sorted(ids)


def test_fw_id_in_version_form(real_hardware: Path) -> None:
    text = generate_channels_cpp(Registry.load(real_hardware), "01JABCDEF0123456789XYZABCD")
    assert 'const char* const FW_ID = "01JABCDEF0123456789XYZABCD";' in text


def test_fw_id_is_escaped(real_hardware: Path) -> None:
    text = generate_channels_cpp(Registry.load(real_hardware), 'a"b\\c\nd')
    assert 'const char* const FW_ID = "a\\"b\\\\c\\nd";' in text


def test_drivers_snapshot(real_hardware: Path) -> None:
    assert generate_drivers_cpp(Registry.load(real_hardware)) == EXPECTED_DRIVERS


def test_ctor_args_follow_manifest_pin_order(tmp_path: Path, real_hardware: Path) -> None:
    src = real_hardware / "ssd1306"
    dst = tmp_path / "ssd1306"
    dst.mkdir()
    for f in src.iterdir():
        (dst / f.name).write_text(f.read_text())
    text = (
        (dst / "manifest.yaml")
        .read_text()
        .replace("pins: { sda: 21, scl: 22 }", "pins: { scl: 22, sda: 21 }")
    )
    (dst / "manifest.yaml").write_text(text)
    out = generate_drivers_cpp(Registry.load(tmp_path))
    assert "static Ssd1306Driver driver_ssd1306(22, 21);" in out
